function runScript(found) {
  if (found) {
    console.log('stdout: result=42');
    return 0;                       // sys.exit(0)
  } else {
    console.log('stderr: error: no input file');
    return 2;                       // sys.exit(2)
  }
}

function shellThen(code) {
  console.log('exit code: ' + code);
  if (code === 0) console.log('NEXT ran');
  else console.log('NEXT skipped (&&  short-circuited)');
}

console.log('--- file present ---');
shellThen(runScript(true));
console.log('--- file missing ---');
shellThen(runScript(false));
